  1841  void pdf_repair_trailer(fz_context *ctx, pdf_document *doc)
  1842  {
  1843          int hasroot, hasinfo;
  1844          pdf_obj *obj, *nobj;
  1845          pdf_obj *dict = NULL;
  1846          int i;
  1847
  1848          int xref_len = pdf_xref_len(ctx, doc);
  1849          pdf_repair_obj_stms(ctx, doc);
  1850
  1851          hasroot = (pdf_dict_get(ctx, pdf_trailer(ctx, doc), PDF_NAME(Root)) != NULL);
  1852          hasinfo = (pdf_dict_get(ctx, pdf_trailer(ctx, doc), PDF_NAME(Info)) != NULL);
  1853
  1854          fz_var(dict);
  1855
  1856          fz_try(ctx)
  1857          {
  1858                  /* Scan from the end so we have a better chance of finding
  1859                   * newer objects if there are multiple instances of Info and
  1860                   * Root objects.
  1861                   */
  1862                  for (i = xref_len - 1; i > 0 && (!hasinfo || !hasroot); --i)
  1863                  {
  1864                          pdf_xref_entry *entry = pdf_get_xref_entry_no_null(ctx, doc, i);
  1865                          if (entry->type == 0 || entry->type == 'f')
  1866                                  continue;
  1867
  1868                          fz_try(ctx)
  1869                          {
  1870                                  dict = pdf_load_object(ctx, doc, i);
  1871                          }
  1872                          fz_catch(ctx)
  1873                          {
  1874                                  fz_rethrow_if(ctx, FZ_ERROR_TRYLATER);
  1875                                  fz_warn(ctx, "ignoring broken object (%d 0 R)", i);
  1876                                  continue;
  1877                          }
  1878
  1879                          if (!hasroot)
  1880                          {
  1881                                  obj = pdf_dict_get(ctx, dict, PDF_NAME(Type));
  1882                                  if (obj == PDF_NAME(Catalog))
  1883                                  {
  1884                                          nobj = pdf_new_indirect(ctx, doc, i, 0);
  1885                                          pdf_dict_put_drop(ctx, pdf_trailer(ctx, doc), PDF_NAME(Root), nobj);
  1886                                          hasroot = 1;
  1887                                  }
  1888                          }
  1889
  1890                          if (!hasinfo)
  1891                          {
  1892                                  if (pdf_dict_get(ctx, dict, PDF_NAME(Creator)) || pdf_dict_get(ctx, dict, PDF_NAME(Producer)))
  1893                                  {
  1894                                          nobj = pdf_new_indirect(ctx, doc, i, 0);
  1895                                          pdf_dict_put_drop(ctx, pdf_trailer(ctx, doc), PDF_NAME(Info), nobj);
  1896                                          hasinfo = 1;
  1897                                  }
  1898                          }
  1899
  1900                          pdf_drop_obj(ctx, dict);
  1901                          dict = NULL;
  1902                  }
  1903          }
  1904          fz_always(ctx)
  1905          {
  1906                  /* ensure that strings are not used in their repaired, non-decrypted form */
  1907                  if (doc->crypt)
  1908                          pdf_clear_xref(ctx, doc);
  1909          }
  1910          fz_catch(ctx)
  1911          {
  1912                  pdf_drop_obj(ctx, dict);
  1913                  fz_rethrow(ctx);
  1914          }
  1915  }
