  2021
  2022  static pdf_xref_entry *
  2023  pdf_load_obj_stm(fz_context *ctx, pdf_document *doc, int num, pdf_lexbuf *buf, int target)
  2024  {
  2025          fz_stream *stm = NULL;
  2026          pdf_obj *objstm = NULL;
  2027          int *numbuf = NULL;
  2028          int64_t *ofsbuf = NULL;
  2029
  2030          pdf_obj *obj;
  2031          int64_t first;
  2032          int count;
  2033          int i;
  2034          pdf_token tok;
  2035          pdf_xref_entry *ret_entry = NULL;
  2036          int xref_len;
  2037          int found;
  2038          fz_stream *sub = NULL;
  2039
  2040          fz_var(numbuf);
  2041          fz_var(ofsbuf);
  2042          fz_var(objstm);
  2043          fz_var(stm);
  2044          fz_var(sub);
  2045
  2046          fz_try(ctx)
  2047          {
  2048                  objstm = pdf_load_object(ctx, doc, num);
  2049
  2050                  if (pdf_obj_marked(ctx, objstm))
  2051                          fz_throw(ctx, FZ_ERROR_GENERIC, "recursive object stream lookup");
  2052          }
  2053          fz_catch(ctx)
  2054          {
  2055                  pdf_drop_obj(ctx, objstm);
  2056                  fz_rethrow(ctx);
  2057          }
  2058
  2059          fz_try(ctx)
  2060          {
  2061                  (void)pdf_mark_obj(ctx, objstm);
  2062
  2063                  count = pdf_dict_get_int(ctx, objstm, PDF_NAME(N));
  2064                  first = pdf_dict_get_int(ctx, objstm, PDF_NAME(First));
  2065
  2066                  validate_object_number_range(ctx, first, count, "object stream");
  2067
  2068                  numbuf = fz_calloc(ctx, count, sizeof(*numbuf));
  2069                  ofsbuf = fz_calloc(ctx, count, sizeof(*ofsbuf));
  2070
  2071                  xref_len = pdf_xref_len(ctx, doc);
  2072
  2073                  found = 0;
  2074
  2075                  stm = pdf_open_stream_number(ctx, doc, num);
  2076                  for (i = 0; i < count; i++)
  2077                  {
  2078                          tok = pdf_lex(ctx, stm, buf);
  2079                          if (tok != PDF_TOK_INT)
  2080                                  fz_throw(ctx, FZ_ERROR_GENERIC, "corrupt object stream (%d 0 R)", num);
  2081                          numbuf[found] = buf->i;
  2082
  2083                          tok = pdf_lex(ctx, stm, buf);
  2084                          if (tok != PDF_TOK_INT)
  2085                                  fz_throw(ctx, FZ_ERROR_GENERIC, "corrupt object stream (%d 0 R)", num);
  2086                          ofsbuf[found] = buf->i;
  2087
  2088                          if (numbuf[found] <= 0 || numbuf[found] >= xref_len)
  2089                                  fz_warn(ctx, "object stream object out of range, skipping");
  2090                          else
  2091                                  found++;
  2092                  }
  2093
  2094                  for (i = 0; i < found; i++)
  2095                  {
  2096                          pdf_xref_entry *entry;
  2097                          uint64_t length;
  2098                          int64_t offset;
  2099
  2100                          offset = first + ofsbuf[i];
  2101                          if (i+1 < found)
  2102                                  length = ofsbuf[i+1] - ofsbuf[i];
  2103                          else
  2104                                  length = UINT64_MAX;
  2105
  2106                          sub = fz_open_null_filter(ctx, stm, length, offset);
  2107
  2108                          obj = pdf_parse_stm_obj(ctx, doc, sub, buf);
  2109                          fz_drop_stream(ctx, sub);
  2110                          sub = NULL;
  2111
  2112                          entry = pdf_get_xref_entry_no_null(ctx, doc, numbuf[i]);
  2113
  2114                          pdf_set_obj_parent(ctx, obj, numbuf[i]);
  2115
  2116                          /* We may have set entry->type to be 'O' from being 'o' to avoid nasty
  2117                           * recursions in pdf_cache_object. Accept the type being 'O' here. */
  2118                          if ((entry->type == 'o' || entry->type == 'O') && entry->ofs == num)
  2119                          {
  2120                                  /* If we already have an entry for this object,
  2121                                   * we'd like to drop it and use the new one -
  2122                                   * but this means that anyone currently holding
  2123                                   * a pointer to the old one will be left with a
  2124                                   * stale pointer. Instead, we drop the new one
  2125                                   * and trust that the old one is correct. */
  2126                                  if (entry->obj)
  2127                                  {
  2128                                          if (pdf_objcmp(ctx, entry->obj, obj))
  2129                                                  fz_warn(ctx, "Encountered new definition for object %d - keeping the original one", numbuf[i]);
  2130                                          pdf_drop_obj(ctx, obj);
  2131                                  }
  2132                                  else
  2133                                  {
  2134                                          entry->obj = obj;
  2135                                          fz_drop_buffer(ctx, entry->stm_buf);
  2136                                          entry->stm_buf = NULL;
  2137                                  }
  2138                                  if (numbuf[i] == target)
  2139                                          ret_entry = entry;
  2140                          }
  2141                          else
  2142                          {
  2143                                  pdf_drop_obj(ctx, obj);
  2144                          }
  2145                  }
  2146          }
  2147          fz_always(ctx)
  2148          {
  2149                  fz_drop_stream(ctx, stm);
  2150                  fz_drop_stream(ctx, sub);
  2151                  fz_free(ctx, ofsbuf);
  2152                  fz_free(ctx, numbuf);
  2153                  pdf_unmark_obj(ctx, objstm);
  2154                  pdf_drop_obj(ctx, objstm);
  2155          }
  2156          fz_catch(ctx)
  2157          {
  2158                  fz_rethrow(ctx);
  2159          }
  2160          return ret_entry;
  2161  }
